  return `<section class="theory-panel" aria-labelledby="theory-title"><div><span class="eyebrow sage">EL HALLAZGO ESTÁ ENTRE DOS PRUEBAS</span><h3 id="theory-title">Contrastar las versiones.</h3><p>El catálogo del hotel utiliza la referencia R-98-17 para justificar la propiedad de la Luna. Contrastadla con la factura original del PDF.</p><p class="micro">Compartid lo que aparece en cada expediente. Esta comprobación es opcional y no cambia los puntos ni bloquea la historia.</p></div><form id="theory-form"><label class="field">¿Qué objeto identifica realmente R-98-17?<input name="answer" required maxlength="100" autocomplete="off" placeholder="Escribid el objeto que habéis encontrado" aria-describedby="theory-result"></label><button class="button" type="submit">Comprobar la conexión ↗</button><div id="theory-result" class="theory-result ${result?.correct?'correct':''}" role="status">${result?esc(result.message):''}</div></form></section>`;
